 ((SELECT id FROM proyectos WHERE nombre='Portal Andes'), (SELECT pf.id FROM perfiles pf JOIN usuarios u ON u.id=pf.usuario_id WHERE u.correo='ana.rios@nexacorp.com'), (SELECT id FROM tipos_evento WHERE codigo='entregable'), 'Kickoff del proyecto — Portal Andes', 'Evento generado para ejercitar el calendario del proyecto Portal Andes.', DATE_ADD(NOW(), INTERVAL 26 DAY), DATE_ADD(NOW(), INTERVAL 26 DAY), (SELECT id FROM tipos_audiencia WHERE codigo='solo_colaboradores'), 'pendiente'),
